    "................",
    "................",
    "...ooo....ooo...",
    "..oRRRo..oRRRo..",
    ".oR**RRooRRRRRo.",
    ".oR*RRRRRRRRRRo.",
    ".oRRRRRRRRRRRro.",
    ".oRRRRRRRRRRRro.",
